    "policy_short": "8th Environment Action Programme",
    "document_type": "decision",
    "policy_area": "Environment",
    "article": "Article 2(2)(a) — thematic objective",
    "target_text": "swift and predictable reduction of greenhouse gas emissions and, at the same time, enhancement of removals by natural sinks in the Union to attain the 2030 greenhouse gas emission reduction target as laid down in Regulation (EU) 2021/1119, in line with the Union’s climate and environment objectives, whilst ensuring a just transition that leaves no one behind;",
    "target_label": "objective",
    "obligation": "mandatory",
    "target_type": "unspecified",
    "timeline": "by 2030",
    "indicators": [
      "greenhouse gas emissions",
      "removals",
      "GHG emission reduction",
      "natural sinks"
    ],
    "climate_relevance": "mitigation",
